  getSongById() {
    const val = window.location.search;
    const daata = val.split("=")
    const song_id = daata[1].slice(0,daata.length-9)
    console.log(daata[2])
    const music_volume = daata[2]
    if (music_volume == 1) {
      //Guitar
      this.setState({
        drumVolume: 0,
        bassVolume: 0,
        guitarVolume: 100,
        keyboardVolume: 0,
        isDrumDisable: true,
        isBassDisable: true,
        isGuitarDisable: false,
        isKeyBoardDisable: true,
      })
    }
    else if (music_volume == 2) {
      //Bass
      this.setState({
        drumVolume: 0,
        bassVolume: 100,
        guitarVolume: 0,
        keyboardVolume: 0,
        isDrumDisable: true,
        isBassDisable: false,
        isGuitarDisable: true,
        isKeyBoardDisable: true,
      })
    }
    else if (music_volume == 3) {
      //Drum
      this.setState({
        drumVolume: 100,
        bassVolume: 0,
        guitarVolume: 0,
        keyboardVolume: 0,
        isDrumDisable: false,
        isBassDisable: true,
        isGuitarDisable: true,
        isKeyBoardDisable: true,
      })
    }
    else if (music_volume == 4) {
      //Keyboard
      this.setState({
        drumVolume: 0,
        bassVolume: 0,
        guitarVolume: 0,
        keyboardVolume: 100,
        isDrumDisable: true,
        isBassDisable: true,
        isGuitarDisable: true,
        isKeyBoardDisable: false,
      })
    }
    this.setState({
      music_volume_handle: music_volume
    })
    const data = {
      // id: 193
      id: song_id
    }
    axios({
      method: "post",
      url: "http://159.223.251.167:3000/fetchSongsById",
      // url: "http://44.197.223.72:4000/getSongsById",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      data: data,
    })
      .then(async (res) => {
        if (res?.data?.success == true) {
          this.setState({
            isPlaying: true,
            playButtonNextAction: 'Play'
          });
          const context = new (window.AudioContext || window.webkitAudioContext)();
          const data_buffers = await Promise.all(
            res?.data?.data[0]?.songs?.map((url) => fetch((url), {
              headers: {
                "access-control-allow-origin": "*",
              },
            }).then((res) => res.arrayBuffer(res)))
          )
          const audio_buffers = await Promise.all(
            data_buffers.map((buf) => context.decodeAudioData(buf))
          );
          this.setState({
            audioBuff: audio_buffers
          });
          for (var i = 0; i < data_buffers.length; i++) {
            this.inputAudio.push({
              name: "Test",
              data: audio_buffers[i],
              source: null,
              gainNode: null,
              gain: 100,
            });
            this.setState({
              playButtonNextAction: 'Play',
              timeA: 0,
              playingAt: 0,
              timeB: this.inputAudio[i].data.duration,
            });
          }
        }
      })
      .catch((err) => {
        console.log(err);
      })
  }

