  setMediaRecorder() {
    if (this.state.micOn) {
      this.mediaRecorder = null;
      this.setState({ micOn: false });
      return;
    }
    const constraints = {
      audio: {
        autoGainControl: false,
        echoCancellation: false,
        latency: this.recLatency,
        noiseSuppression: false,
        sampleRate: 44100,
        sampleSize: 16,
      },
    };
    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
      console.log('getUserMedia supported.');
      navigator.mediaDevices.getUserMedia(constraints)
        .then(stream => {
          this.mediaRecorder = new MediaRecorder(stream);
          this.setState({ micOn: true });
          this.mediaRecorder.ondataavailable = e => {
            this.recordedChunks.push(e.data);
          }
          this.mediaRecorder.onstop = e => {
            stream.getTracks().forEach(t => t.stop());
            const blob = new Blob(this.recordedChunks);
            this.recordedChunks = [];
            this.setState({ micOn: false });
            const fileReader = new FileReader();
            fileReader.onload = () => {
              this.audioCtx.decodeAudioData(fileReader.result,
                audioBuffer => {
                  this.inputAudio.push({
                    name: "recordedTrack",
                    data: audioBuffer,
                    source: null,
                    gainNode: null,
                    gain: 100,
                  });
                  this.setState({ numTracks: this.inputAudio.length });
                },
                error => { console.log("decode error: " + error.err) }
              );
            }
            fileReader.readAsArrayBuffer(blob);
          }
          this.mediaRecorder.start()
        });
    }
  }

